13	int main(int argc, char *argv[])
14	{
15	    smart_home_agent_app_t app;
16	    int ret;
17	
18	    printf("=== Smart Home Agent Demo ===\n");
19	    printf("backend: %s%s model=%s\n",
20	           SMART_HOME_DEMO_HOST,
21	           SMART_HOME_DEMO_PATH,
22	           SMART_HOME_DEMO_MODEL);
23	    if (argc > 1) {
24	        printf("input: %s\n\n", argv[1]);
25	    } else {
26	#ifdef CONFIG_SMART_HOME_DEMO_UI_LVGL
27	        printf("starting LVGL UI\n\n");
28	#else
29	        printf("type 'quit' to exit\n\n");
30	#endif
31	    }
32	
33	    /* Auto-connect WiFi before initializing the agent.
34	     * On platforms without WiFi (e.g. goldfish emulator with Ethernet),
35	     * this may fail — continue anyway and let the HTTP layer use whatever
36	     * network is available.
37	     */
38	
39	    ret = smart_home_wifi_connect();
40	    if (ret < 0) {
41	        syslog(LOG_WARNING, "WiFi connect failed: %d. "
42	               "Continuing with existing network.\n", ret);
43	        fprintf(stderr, "WiFi connect failed: %d (continuing)\n", ret);
44	    }
45	
46	    ret = smart_home_agent_app_init(&app);
47	    if (ret != AGENT_OK) {
48	        fprintf(stderr, "smart_home_agent_app_init failed: %d\n", ret);
49	        return EXIT_FAILURE;
50	    }
51	
52	#ifdef CONFIG_SMART_HOME_DEMO_UI_LVGL
53	    if (argc > 1) {
54	        ret = smart_home_ui_run_once(&app, argv[1]);
55	    } else {
56	        ret = smart_home_lvgl_run(&app, NULL);
57	    }
58	#else
59	    if (argc > 1) {
60	        ret = smart_home_ui_run_once(&app, argv[1]);
61	    } else {
62	        ret = smart_home_ui_run(&app);
63	    }
64	#endif
65	
66	    smart_home_agent_app_deinit(&app);
67	    return ret == AGENT_OK ? EXIT_SUCCESS : EXIT_FAILURE;
68	}
