47	int smart_home_agent_app_init(smart_home_agent_app_t *app)
48	{
49	    agent_model_openai_config_t model_config;
50	    agent_model_t *model;
51	    int ret;
52	
53	    if (!app) {
54	        return AGENT_ERROR_INVALID;
55	    }
56	
57	    memset(app, 0, sizeof(*app));
58	    smart_home_device_init(&app->device_state);
59	    smart_home_skill_store_init(&app->skill_store);
60	    smart_home_model_config_default(&app->model_config);
61	
62	    app->agent = agent_create_simple("smart_home_agent", g_system_prompt);
63	    if (!app->agent) {
64	        return AGENT_ERROR_NOMEM;
65	    }
66	
67	    ret = smart_home_device_register_context(app->agent, &app->device_state);
68	    if (ret != AGENT_OK) {
69	        smart_home_agent_app_deinit(app);
70	        return ret;
71	    }
72	
73	    ret = smart_home_skills_register(app->agent, &app->skill_store);
74	    if (ret != AGENT_OK) {
75	        smart_home_agent_app_deinit(app);
76	        return ret;
77	    }
78	
79	    ret = smart_home_tools_register(app->agent, &app->device_state);
80	    if (ret != AGENT_OK) {
81	        smart_home_agent_app_deinit(app);
82	        return ret;
83	    }
84	
85	    agent_set_event_callback(app->agent,
86	                             smart_home_ui_event_cb,
87	                             &app->run_start_ms);
88	
89	    model_config = agent_model_openai_config_default();
90	    model_config.host = app->model_config.host;
91	    model_config.path = app->model_config.path;
92	    model_config.port = app->model_config.port;
93	    model_config.api_key = app->model_config.api_key;
94	    model_config.model = app->model_config.model;
95	    model_config.timeout_ms = (uint32_t)app->model_config.timeout_ms;
96	    model_config.request_buffer_size = app->model_config.request_buffer_size;
97	    model_config.response_buffer_size = app->model_config.response_buffer_size;
98	
99	    model = agent_model_openai_create(&model_config);
100	    if (!model) {
101	        smart_home_agent_app_deinit(app);
102	        return AGENT_ERROR_NOMEM;
103	    }
104	
105	    ret = agent_set_model_owned(app->agent, model);
106	    if (ret != AGENT_OK) {
107	        agent_model_destroy(model);
108	        smart_home_agent_app_deinit(app);
109	        return ret;
110	    }
111	
112	    ret = smart_home_agent_app_apply_model_config(app, &app->model_config);
113	    if (ret != AGENT_OK) {
114	        smart_home_agent_app_deinit(app);
115	        return ret;
116	    }
117	
118	    return AGENT_OK;
119	}
