134	int smart_home_agent_app_apply_model_config(
135	    smart_home_agent_app_t *app,
136	    const smart_home_model_config_t *config)
137	{
138	    agent_model_t *model;
139	    agent_limits_t limits = AGENT_LIMITS_DEFAULT;
140	    char error[96];
141	    int ret;
142	
143	    if (!app || !app->agent || !config) {
144	        return AGENT_ERROR_INVALID;
145	    }
146	
147	    ret = smart_home_model_config_validate(config, error, sizeof(error));
148	    if (ret != AGENT_OK) {
149	        return ret;
150	    }
151	
152	    model = agent_get_model(app->agent);
153	    if (!model) {
154	        return AGENT_ERROR_MODEL;
155	    }
156	
157	    ret = agent_model_openai_set_backend(model,
158	                                         config->host,
159	                                         config->path,
160	                                         config->port);
161	    if (ret != AGENT_OK) {
162	        return ret;
163	    }
164	
165	    ret = agent_model_openai_set_api_key(model, config->api_key);
166	    if (ret != AGENT_OK) {
167	        return ret;
168	    }
169	
170	    ret = agent_model_openai_set_model(model, config->model);
171	    if (ret != AGENT_OK) {
172	        return ret;
173	    }
174	
175	    limits.timeout_ms = (uint32_t)config->timeout_ms;
176	    limits.per_model_timeout_ms = (uint32_t)config->timeout_ms;
177	    limits.max_output_tokens = config->max_output_tokens > 0u
178	                                   ? config->max_output_tokens
179	                                   : limits.max_output_tokens;
180	    ret = agent_set_limits(app->agent, &limits);
181	    if (ret != AGENT_OK) {
182	        return ret;
183	    }
184	
185	    app->model_config = *config;
186	    return AGENT_OK;
187	}
