189	int smart_home_agent_run(smart_home_agent_app_t *app,
190	                         const char *input,
191	                         char *output,
192	                         size_t output_size)
193	{
194	    agent_request_t request;
195	    agent_response_t response;
196	
197	    if (!app || !app->agent || !input || !output || output_size == 0u) {
198	        return AGENT_ERROR_INVALID;
199	    }
200	
201	    memset(&request, 0, sizeof(request));
202	    memset(&response, 0, sizeof(response));
203	
204	    request.session_id = SMART_HOME_SESSION_ID;
205	    request.input = input;
206	    response.output = output;
207	    response.output_size = output_size;
208	
209	    return agent_run(app->agent, &request, &response);
210	}
