82	static const char *find_json_value(const char *json, const char *key)
83	{
84	    const char *p;
85	
86	    if (!json || !key) {
87	        return NULL;
88	    }
89	
90	    p = strstr(json, key);
91	    if (!p) {
92	        return NULL;
93	    }
94	
95	    p = strchr(p + strlen(key), ':');
96	    if (!p) {
97	        return NULL;
98	    }
99	
100	    p++;
101	    while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n') {
102	        p++;
103	    }
104	
105	    return p;
106	}
