108	static int json_get_int(const char *json, const char *key, int *out)
109	{
110	    const char *p = find_json_value(json, key);
111	    char *end = NULL;
112	    long value;
113	
114	    if (!p || !out) {
115	        return AGENT_ERROR_INVALID;
116	    }
117	
118	    value = strtol(p, &end, 10);
119	    if (end == p) {
120	        return AGENT_ERROR_INVALID;
121	    }
122	
123	    *out = (int)value;
124	    return AGENT_OK;
125	}
