127	static int json_get_bool(const char *json, const char *key, int *out)
128	{
129	    const char *p = find_json_value(json, key);
130	
131	    if (!p || !out) {
132	        return AGENT_ERROR_INVALID;
133	    }
134	
135	    if (strncmp(p, "true", 4) == 0) {
136	        *out = 1;
137	        return AGENT_OK;
138	    }
139	
140	    if (strncmp(p, "false", 5) == 0) {
141	        *out = 0;
142	        return AGENT_OK;
143	    }
144	
145	    return AGENT_ERROR_INVALID;
146	}
