148	static int json_get_string(const char *json,
149	                           const char *key,
150	                           char *out,
151	                           size_t out_size)
152	{
153	    const char *p = find_json_value(json, key);
154	    size_t used = 0u;
155	
156	    if (!p || !out || out_size == 0u || *p != '"') {
157	        return AGENT_ERROR_INVALID;
158	    }
159	
160	    p++;
161	    while (*p && *p != '"' && used + 1u < out_size) {
162	        if (*p == '\\' && p[1]) {
163	            p++;
164	            if (*p == 'n') {
165	                out[used++] = '\n';
166	            } else if (*p == 'r') {
167	                out[used++] = '\r';
168	            } else if (*p == 't') {
169	                out[used++] = '\t';
170	            } else {
171	                out[used++] = *p;
172	            }
173	            p++;
174	            continue;
175	        }
176	        out[used++] = *p++;
177	    }
178	    out[used] = '\0';
179	
180	    return *p == '"' ? AGENT_OK : AGENT_ERROR_LIMIT;
181	}
