183	static void json_escape_string(const char *in, char *out, size_t out_size)
184	{
185	    size_t used = 0u;
186	
187	    if (!out || out_size == 0u) {
188	        return;
189	    }
190	
191	    while (in && *in && used + 1u < out_size) {
192	        if ((*in == '"' || *in == '\\') && used + 2u < out_size) {
193	            out[used++] = '\\';
194	            out[used++] = *in++;
195	            continue;
196	        }
197	        if (*in == '\n' && used + 2u < out_size) {
198	            out[used++] = '\\';
199	            out[used++] = 'n';
200	            in++;
201	            continue;
202	        }
203	        if (*in == '\r' && used + 2u < out_size) {
204	            out[used++] = '\\';
205	            out[used++] = 'r';
206	            in++;
207	            continue;
208	        }
209	        if (*in == '\t' && used + 2u < out_size) {
210	            out[used++] = '\\';
211	            out[used++] = 't';
212	            in++;
213	            continue;
214	        }
215	        out[used++] = *in++;
216	    }
217	    out[used] = '\0';
218	}
