220	static unsigned int weather_hash_location(const char *location)
221	{
222	    unsigned int hash = 5381u;
223	
224	    while (location && *location) {
225	        hash = ((hash << 5) + hash) + (unsigned char)*location++;
226	    }
227	
228	    return hash;
229	}
