231	static smart_home_weather_t weather_for_location(const char *location)
232	{
233	    smart_home_weather_t weather;
234	    unsigned int hash;
235	    static const char *conditions[] = {
236	        "clear",
237	        "partly_cloudy",
238	        "cloudy",
239	        "light_rain",
240	        "hot",
241	    };
242	    static const char *winds[] = {
243	        "calm",
244	        "light",
245	        "moderate",
246	    };
247	
248	    if (location && strcmp(location, "Shanghai") == 0) {
249	        weather.condition = "light_rain";
250	        weather.temperature = 27;
251	        weather.humidity = 78;
252	        weather.wind = "moderate";
253	        return weather;
254	    }
255	
256	    if (location && strcmp(location, "Beijing") == 0) {
257	        weather.condition = "clear";
258	        weather.temperature = 30;
259	        weather.humidity = 36;
260	        weather.wind = "light";
261	        return weather;
262	    }
263	
264	    if (location && strcmp(location, "Shenzhen") == 0) {
265	        weather.condition = "cloudy";
266	        weather.temperature = 29;
267	        weather.humidity = 82;
268	        weather.wind = "moderate";
269	        return weather;
270	    }
271	
272	    hash = weather_hash_location(location);
273	    weather.condition = conditions[hash % 5u];
274	    weather.temperature = 18 + (int)(hash % 16u);
275	    weather.humidity = 35 + (int)((hash / 7u) % 55u);
276	    weather.wind = winds[(hash / 17u) % 3u];
277	    return weather;
278	}
