506	static int set_timer_tool(const agent_tool_call_t *call,
507	                          agent_tool_result_t *result,
508	                          void *user_data)
509	{
510	    static char output[512];
511	    smart_home_timer_t *timer;
512	    char message[128] = "";
513	    char escaped_message[256];
514	    char name[32] = "";
515	    char escaped_name[64];
516	    int delay_seconds = 0;
517	    int slot;
518	    int ret;
519	    time_t now;
520	
521	    (void)user_data;
522	
523	    ret = json_get_int(call->arguments_json,
524	                       "\"delay_seconds\"",
525	                       &delay_seconds);
526	    if (ret == AGENT_OK) {
527	        ret = json_get_string(call->arguments_json,
528	                              "\"message\"",
529	                              message,
530	                              sizeof(message));
531	    }
532	    if (ret == AGENT_OK && delay_seconds <= 0) {
533	        ret = AGENT_ERROR_INVALID;
534	    }
535	    if (ret == AGENT_OK) {
536	        if (json_get_string(call->arguments_json,
537	                            "\"name\"",
538	                            name,
539	                            sizeof(name)) != AGENT_OK ||
540	            name[0] == '\0') {
541	            snprintf(name, sizeof(name), "timer_%d", g_next_timer_id);
542	        }
543	    }
544	
545	    slot = ret == AGENT_OK ? timer_find_slot() : -1;
546	    if (ret == AGENT_OK && slot < 0) {
547	        ret = AGENT_ERROR_LIMIT;
548	    }
549	
550	    if (ret == AGENT_OK) {
551	        now = time(NULL);
552	        timer = &g_timers[slot];
553	        memset(timer, 0, sizeof(*timer));
554	        timer->active = 1;
555	        timer->id = g_next_timer_id++;
556	        timer->delay_seconds = delay_seconds;
557	        timer->created_epoch = (long long)now;
558	        timer->due_epoch = (long long)now + delay_seconds;
559	        strncpy(timer->name, name, sizeof(timer->name) - 1);
560	        strncpy(timer->message, message, sizeof(timer->message) - 1);
561	        json_escape_string(timer->name, escaped_name, sizeof(escaped_name));
562	        json_escape_string(timer->message,
563	                           escaped_message,
564	                           sizeof(escaped_message));
565	
566	        snprintf(output,
567	                 sizeof(output),
568	                 "{\"ok\":true,\"id\":%d,\"name\":\"%s\","
569	                 "\"delay_seconds\":%d,\"due_epoch\":%lld,"
570	                 "\"message\":\"%s\"}",
571	                 timer->id,
572	                 escaped_name,
573	                 timer->delay_seconds,
574	                 timer->due_epoch,
575	                 escaped_message);
576	    } else {
577	        snprintf(output, sizeof(output), "{\"ok\":false}");
578	    }
579	
580	    result->status = ret;
581	    result->content_json = output;
582	    result->error_message = ret == AGENT_OK ? NULL : "set_timer failed";
583	    return ret;
584	}
