586	static int list_timers_tool(const agent_tool_call_t *call,
587	                            agent_tool_result_t *result,
588	                            void *user_data)
589	{
590	    static char output[768];
591	    size_t off = 0u;
592	    int count = 0;
593	    int i;
594	    time_t now;
595	
596	    (void)call;
597	    (void)user_data;
598	
599	    now = time(NULL);
600	    off += snprintf(output + off, sizeof(output) - off, "{\"timers\":[");
601	    for (i = 0; i < SMART_HOME_MAX_TIMERS && off < sizeof(output); i++) {
602	        const smart_home_timer_t *timer = &g_timers[i];
603	        char escaped_name[64];
604	        char escaped_message[256];
605	        long long remaining;
606	
607	        if (!timer->active) {
608	            continue;
609	        }
610	
611	        remaining = timer->due_epoch - (long long)now;
612	        json_escape_string(timer->name, escaped_name, sizeof(escaped_name));
613	        json_escape_string(timer->message,
614	                           escaped_message,
615	                           sizeof(escaped_message));
616	        if (count > 0) {
617	            off += snprintf(output + off, sizeof(output) - off, ",");
618	        }
619	        off += snprintf(output + off,
620	                        sizeof(output) - off,
621	                        "{\"id\":%d,\"name\":\"%s\","
622	                        "\"message\":\"%s\",\"remaining_seconds\":%lld,"
623	                        "\"expired\":%s}",
624	                        timer->id,
625	                        escaped_name,
626	                        escaped_message,
627	                        remaining > 0 ? remaining : 0,
628	                        remaining <= 0 ? "true" : "false");
629	        count++;
630	    }
631	    if (off < sizeof(output)) {
632	        off += snprintf(output + off,
633	                        sizeof(output) - off,
634	                        "],\"count\":%d}",
635	                        count);
636	    }
637	
638	    result->status = off < sizeof(output) ? AGENT_OK : AGENT_ERROR_LIMIT;
639	    result->content_json = output;
640	    result->error_message =
641	        result->status == AGENT_OK ? NULL : "list_timers failed";
642	    return result->status;
643	}
