81	static void copy_json_safe_name(char *dest,
82	                                size_t dest_size,
83	                                const char *src,
84	                                const char *fallback)
85	{
86	    const char *input = (src && src[0]) ? src : fallback;
87	    size_t i;
88	
89	    if (!dest || dest_size == 0u) {
90	        return;
91	    }
92	
93	    for (i = 0; i + 1u < dest_size && input && input[i]; i++) {
94	        char ch = input[i];
95	
96	        if (ch == '"' || ch == '\\' || (unsigned char)ch < 0x20u) {
97	            ch = ' ';
98	        }
99	        dest[i] = ch;
100	    }
101	    dest[i] = '\0';
102	}
