521	static int append_text(char *buffer, size_t size, size_t *off, const char *text)
522	{
523	    int n;
524	
525	    if (*off >= size) {
526	        return AGENT_ERROR_LIMIT;
527	    }
528	
529	    n = snprintf(buffer + *off, size - *off, "%s", text);
530	    if (n < 0 || (size_t)n >= size - *off) {
531	        return AGENT_ERROR_LIMIT;
532	    }
533	
534	    *off += (size_t)n;
535	    return AGENT_OK;
536	}
537	
538	static int append_device_json(char *buffer,
539	                              size_t size,
540	                              size_t *off,
541	                              const smart_home_device_t *device,
542	                              int first)
543	{
544	    int n;
545	
546	    if (*off >= size) {
547	        return AGENT_ERROR_LIMIT;
548	    }
549	
550	    if (device->type == SMART_HOME_DEVICE_AC) {
551	        n = snprintf(buffer + *off,
552	                     size - *off,
553	                     "%s{\"id\":%d,\"room\":\"%s\",\"name\":\"%s\","
554	                     "\"type\":\"ac\",\"on\":%s,\"temperature\":%d,"
555	                     "\"mode\":\"%s\",\"fan_speed\":\"%s\"}",
556	                     first ? "" : ",",
557	                     device->id,
558	                     device->room,
559	                     device->name,
560	                     device->on ? "true" : "false",
561	                     device->temperature,
562	                     smart_home_ac_mode_name(device->ac_mode),
563	                     smart_home_ac_fan_speed_name(device->ac_fan_speed));
564	    } else {
565	        n = snprintf(buffer + *off,
566	                     size - *off,
567	                     "%s{\"id\":%d,\"room\":\"%s\",\"name\":\"%s\","
568	                     "\"type\":\"light\",\"on\":%s,\"brightness\":%d}",
569	                     first ? "" : ",",
570	                     device->id,
571	                     device->room,
572	                     device->name,
573	                     device->on ? "true" : "false",
574	                     device->brightness);
575	    }
576	
577	    if (n < 0 || (size_t)n >= size - *off) {
578	        return AGENT_ERROR_LIMIT;
579	    }
580	
581	    *off += (size_t)n;
582	    return AGENT_OK;
583	}
584	
585	int smart_home_device_build_status_json(const smart_home_state_t *state,
586	                                        char *buffer,
587	                                        size_t buffer_size)
588	{
589	    size_t off = 0u;
590	    int first = 1;
591	    int i;
592	    int ret;
593	    int n;
594	
595	    if (!state || !buffer || buffer_size == 0u) {
596	        return AGENT_ERROR_INVALID;
597	    }
598	
599	    ret = append_text(buffer, buffer_size, &off, "{\"devices\":[");
600	    if (ret != AGENT_OK) {
601	        return ret;
602	    }
603	
604	    for (i = 0; i < SMART_HOME_MAX_DEVICES; i++) {
605	        const smart_home_device_t *device = &state->devices[i];
606	
607	        if (!device->used) {
608	            continue;
609	        }
610	        ret = append_device_json(buffer, buffer_size, &off, device, first);
611	        if (ret != AGENT_OK) {
612	            return ret;
613	        }
614	        first = 0;
615	    }
616	
617	    n = snprintf(buffer + off,
618	                 buffer_size - off,
619	                 "],\"environment\":{\"temperature\":%d,"
620	                 "\"humidity\":%d,\"ambient_light\":%d}}",
621	                 state->env_temperature,
622	                 state->env_humidity,
623	                 state->env_light);
624	    if (n < 0 || (size_t)n >= buffer_size - off) {
625	        return AGENT_ERROR_LIMIT;
626	    }
627	
628	    return AGENT_OK;
629	}
630	
631	static int build_device_context(char *buffer,
632	                                size_t buffer_size,
633	                                size_t *written,
634	                                void *user_data)
635	{
636	    smart_home_state_t *state = (smart_home_state_t *)user_data;
637	    char status[1024];
638	    int ret;
639	    int n;
640	
641	    if (!buffer || !written || !state) {
642	        return AGENT_ERROR_INVALID;
643	    }
644	
645	    ret = smart_home_device_build_status_json(state, status, sizeof(status));
646	    if (ret != AGENT_OK) {
647	        return ret;
648	    }
649	
650	    n = snprintf(buffer,
651	                 buffer_size,
652	                 "Current virtual home state JSON:\n%s\n",
653	                 status);
654	    if (n < 0 || (size_t)n >= buffer_size) {
655	        return AGENT_ERROR_CONTEXT_OVERFLOW;
656	    }
657	
658	    *written = (size_t)n;
659	    return AGENT_OK;
660	}
661	
662	int smart_home_device_register_context(agent_t *agent,
663	                                       smart_home_state_t *state)
664	{
665	    agent_context_provider_t provider;
666	
667	    if (!agent || !state) {
668	        return AGENT_ERROR_INVALID;
669	    }
670	
671	    memset(&provider, 0, sizeof(provider));
672	    provider.name = "smart_home_state";
673	    provider.priority = 80u;
674	    provider.flags = AGENT_CONTEXT_FLAG_OPTIONAL;
675	    provider.build = build_device_context;
676	    provider.user_data = state;
677	
678	    return agent_register_context_provider(agent, &provider);
679	}
