1	/**
2	 * smart_home LVGL agent bridge.
3	 */
4	
5	#include "smart_home_lvgl_internal.h"
6	
7	#include "../../config/smart_home_config.h"
8	
9	#include <pthread.h>
10	#include <stdlib.h>
11	#include <stdio.h>
12	#include <string.h>
13	
14	typedef struct {
15	    smart_home_lvgl_t *ui;
16	    char input[SMART_HOME_INPUT_SIZE];
17	} agent_job_t;
18	
19	typedef struct {
20	    smart_home_lvgl_t *ui;
21	    int ret;
22	    char output[SMART_HOME_OUTPUT_SIZE];
23	} agent_done_t;
24	
25	typedef struct {
26	    smart_home_lvgl_t *ui;
27	    agent_event_type_t type;
28	    uint32_t iteration;
29	    int error_code;
30	    char message[128];
31	    char tool_name[64];
32	    char tool_call_id[64];
33	} ui_event_payload_t;
34	
35	static void agent_done_async_cb(void *data)
36	{
37	    agent_done_t *done = (agent_done_t *)data;
38	    smart_home_lvgl_t *ui = done ? done->ui : NULL;
39	
40	    if (!done) {
41	        return;
42	    }
43	
44	    if (ui) {
45	        ui->request_inflight = 0;
46	        if (done->ret == AGENT_OK) {
47	            smart_home_lvgl_finish_thinking(ui);
48	            smart_home_lvgl_append_msg_bubble(ui, done->output, 0);
49	            smart_home_lvgl_refresh_cards(ui);
50	        } else {
51	            char message[160];
52	            snprintf(message,
53	                     sizeof(message),
54	                     "Agent call failed (%d): %.96s",
55	                     done->ret,
56	                     done->output[0] ? done->output : "no detail");
57	            smart_home_lvgl_finish_thinking(ui);
58	            smart_home_lvgl_append_error_bubble(ui, message);
59	        }
60	        /* Update status hint */
61	        if (ui->chat_status) {
62	            lv_label_set_text(ui->chat_status,
63	                              "Done.  (NSH: smart_home \"...\")");
64	        }
65	    }
66	
67	    free(done);
68	}
69	
70	static void *agent_worker_main(void *arg)
71	{
72	    agent_job_t *job = (agent_job_t *)arg;
73	    agent_done_t *done;
74	
75	    if (!job) {
76	        return NULL;
77	    }
78	
79	    done = (agent_done_t *)calloc(1, sizeof(*done));
80	    if (!done) {
81	        if (job->ui) {
82	            job->ui->request_inflight = 0;
83	        }
84	        free(job);
85	        return NULL;
86	    }
87	
88	    done->ui = job->ui;
89	    done->ret = smart_home_agent_run(job->ui->app,
90	                                     job->input,
91	                                     done->output,
92	                                     sizeof(done->output));
93	    lv_async_call(agent_done_async_cb, done);
94	    free(job);
95	    return NULL;
96	}
97	
98	int smart_home_lvgl_submit_agent_job(smart_home_lvgl_t *ui, const char *text)
99	{
100	    pthread_t tid;
101	    agent_job_t *job;
102	    int ret;
103	
104	    if (!ui || !ui->app || !text || !text[0]) {
105	        return AGENT_ERROR_INVALID;
106	    }
107	
108	    if (ui->request_inflight) {
109	        smart_home_lvgl_append_error_bubble(ui, "Previous request is still running.");
110	        return AGENT_ERROR_BUSY;
111	    }
112	
113	    job = (agent_job_t *)calloc(1, sizeof(*job));
114	    if (!job) {
115	        smart_home_lvgl_append_error_bubble(ui, "Not enough memory to submit request.");
116	        return AGENT_ERROR_NOMEM;
117	    }
118	
119	    job->ui = ui;
120	    strncpy(job->input, text, sizeof(job->input) - 1);
121	    ui->request_inflight = 1;
122	
123	    {
124	        pthread_attr_t attr;
125	
126	        pthread_attr_init(&attr);
127	        pthread_attr_setstacksize(&attr, 65536);
128	        ret = pthread_create(&tid, &attr, agent_worker_main, job);
129	        pthread_attr_destroy(&attr);
130	    }
131	    if (ret != 0) {
132	        ui->request_inflight = 0;
133	        free(job);
134	        smart_home_lvgl_append_error_bubble(ui, "Failed to create Agent worker.");
135	        return AGENT_ERROR;
136	    }
137	
138	    pthread_detach(tid);
139	    return AGENT_OK;
140	}
141	
142	static void ui_event_async_cb(void *data)
143	{
144	    ui_event_payload_t *payload = (ui_event_payload_t *)data;
145	    smart_home_lvgl_t *ui;
146	
147	    if (!payload) {
148	        return;
149	    }
150	
151	    ui = payload->ui;
152	    if (!ui) {
153	        free(payload);
154	        return;
155	    }
156	
157	    switch (payload->type) {
158	    case AGENT_EVENT_MODEL_REQUEST:
159	        smart_home_lvgl_show_thinking(ui);
160	        break;
161	    case AGENT_EVENT_TOOL_CALL:
162	        smart_home_lvgl_trace_tool(ui,
163	                                   payload->tool_name,
164	                                   payload->tool_call_id,
165	                                   -1);
166	        break;
167	    case AGENT_EVENT_TOOL_RESULT:
168	        if (strcmp(payload->tool_name, "set_light") == 0 ||
169	            strcmp(payload->tool_name, "set_ac") == 0 ||
170	            strcmp(payload->tool_name, "run_scene") == 0) {
171	            smart_home_lvgl_refresh_cards(ui);
172	        }
173	        smart_home_lvgl_trace_tool(ui,
174	                                   payload->tool_name,
175	                                   payload->tool_call_id,
176	                                   payload->error_code == AGENT_OK ? 1 : 0);
177	        break;
178	    case AGENT_EVENT_ERROR:
179	    case AGENT_EVENT_TIMEOUT:
180	        smart_home_lvgl_finish_thinking(ui);
181	        smart_home_lvgl_append_error_bubble(ui, payload->message);
182	        break;
183	    case AGENT_EVENT_RUN_DONE:
184	        if (payload->error_code != AGENT_OK) {
185	            smart_home_lvgl_finish_thinking(ui);
186	            smart_home_lvgl_append_error_bubble(ui, payload->message);
187	        }
188	        break;
189	    default:
190	        break;
191	    }
192	
193	    free(payload);
194	}
195	
196	void smart_home_lvgl_event_cb(const agent_event_t *event, void *user_data)
197	{
198	    smart_home_lvgl_t *ui = (smart_home_lvgl_t *)user_data;
199	    ui_event_payload_t *payload;
200	
201	    if (!ui || !event) {
202	        return;
203	    }
204	
205	    payload = (ui_event_payload_t *)calloc(1, sizeof(*payload));
206	    if (!payload) {
207	        return;
208	    }
209	
210	    payload->ui = ui;
211	    payload->type = event->type;
212	    payload->iteration = event->iteration;
213	    payload->error_code = event->error_code;
214	
215	    if (event->message) {
216	        strncpy(payload->message, event->message, sizeof(payload->message) - 1);
217	    }
218	    if (event->tool_name) {
219	        strncpy(payload->tool_name,
220	                event->tool_name,
221	                sizeof(payload->tool_name) - 1);
222	    }
223	    if (event->tool_call_id) {
224	        strncpy(payload->tool_call_id,
225	                event->tool_call_id,
226	                sizeof(payload->tool_call_id) - 1);
227	    }
228	
229	    lv_async_call(ui_event_async_cb, payload);
230	}
