232	static void refresh_trace_header(smart_home_lvgl_t *ui)
233	{
234	    int has_running = 0;
235	    int has_failed = 0;
236	
237	    if (!ui || !ui->chat_trace_status) {
238	        return;
239	    }
240	
241	    for (int i = 0; i < ui->chat_trace_tool_count; i++) {
242	        if (ui->chat_trace_tools[i].state < 0) {
243	            has_running = 1;
244	        } else if (ui->chat_trace_tools[i].state == 0) {
245	            has_failed = 1;
246	        }
247	    }
248	
249	    if (has_running) {
250	        lv_label_set_text(ui->chat_trace_status, "Running");
251	        lv_obj_set_style_text_color(ui->chat_trace_status,
252	                                    SMART_HOME_UI_COLOR_WARNING,
253	                                    0);
254	    } else if (has_failed) {
255	        lv_label_set_text(ui->chat_trace_status, "Failed");
256	        lv_obj_set_style_text_color(ui->chat_trace_status,
257	                                    SMART_HOME_UI_COLOR_DANGER,
258	                                    0);
259	    } else if (ui->chat_trace_tool_count > 0) {
260	        lv_label_set_text(ui->chat_trace_status, "OK");
261	        lv_obj_set_style_text_color(ui->chat_trace_status,
262	                                    SMART_HOME_UI_COLOR_SUCCESS,
263	                                    0);
264	    } else if (ui->chat_trace_active) {
265	        lv_label_set_text(ui->chat_trace_status, "Running");
266	        lv_obj_set_style_text_color(ui->chat_trace_status,
267	                                    SMART_HOME_UI_COLOR_WARNING,
268	                                    0);
269	    } else {
270	        lv_label_set_text(ui->chat_trace_status, "Done");
271	        lv_obj_set_style_text_color(ui->chat_trace_status,
272	                                    SMART_HOME_UI_COLOR_SUCCESS,
273	                                    0);
274	    }
275	}
