412	void smart_home_lvgl_trace_tool(smart_home_lvgl_t *ui,
413	                                const char *name,
414	                                const char *call_id,
415	                                int ok)
416	{
417	    lv_obj_t *tool_row;
418	    lv_obj_t *label;
419	    smart_home_lvgl_trace_tool_t *tool;
420	    const char *id = call_id && call_id[0] ? call_id : "-";
421	    const char *tool_name = name && name[0] ? name : "tool";
422	    char text[128];
423	    int slot = -1;
424	
425	    if (!ui || !ui->chat_list) {
426	        return;
427	    }
428	
429	    ensure_trace_card(ui);
430	    if (!ui->chat_trace_body) {
431	        return;
432	    }
433	
434	    for (int i = 0; i < ui->chat_trace_tool_count; i++) {
435	        if (strcmp(ui->chat_trace_tools[i].id, id) == 0) {
436	            slot = i;
437	            break;
438	        }
439	    }
440	
441	    if (slot < 0 && ok >= 0) {
442	        for (int i = ui->chat_trace_tool_count - 1; i >= 0; i--) {
443	            if (ui->chat_trace_tools[i].state < 0 &&
444	                strcmp(ui->chat_trace_tools[i].name, tool_name) == 0) {
445	                slot = i;
446	                break;
447	            }
448	        }
449	    }
450	
451	    if (slot >= 0) {
452	        tool = &ui->chat_trace_tools[slot];
453	        tool->state = ok;
454	        if (tool->status_label) {
455	            lv_label_set_text(tool->status_label, tool_status_text(ok));
456	            lv_obj_set_style_text_color(tool->status_label,
457	                                        tool_status_color(ok),
458	                                        0);
459	        }
460	        refresh_trace_header(ui);
461	        scroll_chat_to_bottom(ui);
462	        return;
463	    }
464	
465	    if (ui->chat_trace_tool_count >= SMART_HOME_LVGL_TRACE_TOOL_MAX) {
466	        scroll_chat_to_bottom(ui);
467	        return;
468	    }
469	
470	    slot = ui->chat_trace_tool_count++;
471	    tool = &ui->chat_trace_tools[slot];
472	    strncpy(tool->id, id, sizeof(tool->id) - 1);
473	    strncpy(tool->name, tool_name, sizeof(tool->name) - 1);
474	    tool->state = ok;
475	
476	    tool_row = lv_obj_create(ui->chat_trace_body);
477	    lv_obj_remove_style_all(tool_row);
478	    lv_obj_set_size(tool_row, lv_pct(100), LV_SIZE_CONTENT);
479	    lv_obj_clear_flag(tool_row, LV_OBJ_FLAG_CLICKABLE);
480	    lv_obj_set_style_bg_opa(tool_row, LV_OPA_TRANSP, 0);
481	    lv_obj_set_style_border_width(tool_row, 0, 0);
482	    lv_obj_set_style_pad_all(tool_row, 0, 0);
483	    lv_obj_set_flex_flow(tool_row, LV_FLEX_FLOW_ROW);
484	    lv_obj_set_flex_align(tool_row,
485	                          LV_FLEX_ALIGN_START,
486	                          LV_FLEX_ALIGN_CENTER,
487	                          LV_FLEX_ALIGN_CENTER);
488	    lv_obj_set_style_pad_column(tool_row, 6, 0);
489	    tool->row = tool_row;
490	
491	    smart_home_lvgl_icon_create(tool_row, ICON_TOOL, 14, 14);
492	    snprintf(text,
493	             sizeof(text),
494	             "%s  %s",
495	             tool_name,
496	             id);
497	    label = smart_home_lvgl_label_create(tool_row,
498	                                         text,
499	                                         SMART_HOME_UI_COLOR_TEXT_PRIMARY,
500	                                         12);
501	    lv_label_set_long_mode(label, LV_LABEL_LONG_DOT);
502	    lv_obj_set_width(label, smart_home_lvgl_content_w() * 48 / 100);
503	    lv_obj_set_flex_grow(label, 1);
504	
505	    tool->status_label = smart_home_lvgl_label_create(tool_row,
506	                                                      tool_status_text(ok),
507	                                                      tool_status_color(ok),
508	                                                      12);
509	    refresh_trace_header(ui);
510	    scroll_chat_to_bottom(ui);
511	}
