623	    row = create_chat_row(ui, 0);
624	    width = smart_home_lvgl_content_w() * 78 / 100;
625	    bubble = lv_obj_create(row);
626	    lv_obj_remove_style_all(bubble);
627	    lv_obj_set_width(bubble, width);
628	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
629	    lv_obj_clear_flag(bubble, LV_OBJ_FLAG_CLICKABLE);
630	    smart_home_lvgl_card_style(bubble);
631	    smart_home_lvgl_set_bg(bubble, SMART_HOME_UI_COLOR_ERROR_BUBBLE_BG);
632	    lv_obj_set_style_border_side(bubble, LV_BORDER_SIDE_LEFT, 0);
633	    lv_obj_set_style_border_width(bubble, 3, 0);
634	    lv_obj_set_style_border_color(bubble, SMART_HOME_UI_COLOR_WARNING, 0);
635	
636	    snprintf(text, sizeof(text), "Error: %s", msg ? msg : "no detail");
637	    label = smart_home_lvgl_label_create(bubble,
638	                                         text,
639	                                         SMART_HOME_UI_COLOR_TEXT_PRIMARY,
640	                                         12);
641	    lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
642	    lv_obj_set_width(label, width - 20);
643	    scroll_chat_to_bottom(ui);
