90	static void smart_home_lvgl_uv_loop(uv_loop_t *loop,
91	                                    lv_nuttx_result_t *result)
92	{
93	    lv_nuttx_uv_t uv_info;
94	    void *data;
95	
96	    uv_loop_init(loop);
97	    lv_memzero(&uv_info, sizeof(uv_info));
98	    uv_info.loop = loop;
99	    uv_info.disp = result->disp;
100	    uv_info.indev = result->indev;
101	#ifdef CONFIG_UINPUT_TOUCH
102	    uv_info.uindev = result->utouch_indev;
103	#endif
104	#ifdef CONFIG_LV_USE_NUTTX_MOUSE
105	    uv_info.mouse_indev = result->mouse_indev;
106	#endif
107	
108	    data = lv_nuttx_uv_init(&uv_info);
109	    uv_run(loop, UV_RUN_DEFAULT);
110	    lv_nuttx_uv_deinit(&data);
111	}
112	#endif
113	
114	int smart_home_lvgl_run(smart_home_agent_app_t *app,
115	                        const char *initial_input)
116	{
117	    lv_nuttx_dsc_t info;
118	    lv_nuttx_result_t result;
119	    smart_home_lvgl_t *ui;
120	
121	#ifdef CONFIG_LV_USE_NUTTX_LIBUV
122	    uv_loop_t ui_loop;
123	    lv_memzero(&ui_loop, sizeof(ui_loop));
124	#endif
125	
126	    if (!app) {
127	        return AGENT_ERROR_INVALID;
128	    }
129	
130	    if (lv_is_initialized()) {
131	        return AGENT_ERROR_BUSY;
132	    }
133	
134	#ifdef NEED_BOARDINIT
135	    boardctl(BOARDIOC_INIT, 0);
136	#endif
137	
138	    lv_init();
139	    smart_home_lvgl_style_init();
140	    lv_nuttx_dsc_init(&info);
141	
142	#ifdef CONFIG_LV_USE_NUTTX_LCD
143	    info.fb_path = "/dev/lcd0";
144	#endif
145	
146	#ifdef CONFIG_INPUT_TOUCHSCREEN
147	    info.input_path = SMART_HOME_TOUCH_PATH;
148	#endif
149	
150	    lv_nuttx_init(&info, &result);
151	    if (!result.disp) {
152	        smart_home_lvgl_style_deinit();
153	        lv_deinit();
154	        return AGENT_ERROR;
