73	static void *agent_worker_main(void *arg)
74	{
75	    agent_job_t *job = (agent_job_t *)arg;
76	    agent_done_t *done;
77	
78	    if (!job) {
79	        return NULL;
80	    }
81	
82	    done = (agent_done_t *)calloc(1, sizeof(*done));
83	    if (!done) {
84	        if (job->ui) {
85	            job->ui->request_inflight = 0;
86	        }
87	        free(job);
88	        return NULL;
89	    }
90	
91	    done->ui = job->ui;
92	    done->ret = smart_home_agent_run(job->ui->app,
93	                                     job->input,
94	                                     done->output,
95	                                     sizeof(done->output));
96	    lv_async_call(agent_done_async_cb, done);
97	    free(job);
98	    return NULL;
99	}
