145	static void ui_event_async_cb(void *data)
146	{
147	    ui_event_payload_t *payload = (ui_event_payload_t *)data;
148	    smart_home_lvgl_t *ui;
149	
150	    if (!payload) {
151	        return;
152	    }
153	
154	    ui = payload->ui;
155	    if (!ui) {
156	        free(payload);
157	        return;
158	    }
159	
160	    switch (payload->type) {
161	    case AGENT_EVENT_MODEL_REQUEST:
162	        smart_home_lvgl_show_thinking(ui);
163	        break;
164	    case AGENT_EVENT_TOOL_CALL:
165	        smart_home_lvgl_trace_tool(ui,
166	                                   payload->tool_name,
167	                                   payload->tool_call_id,
168	                                   -1);
169	        break;
170	    case AGENT_EVENT_TOOL_RESULT:
171	        if (strcmp(payload->tool_name, "set_light") == 0 ||
172	            strcmp(payload->tool_name, "set_ac") == 0 ||
173	            strcmp(payload->tool_name, "run_scene") == 0) {
174	            smart_home_lvgl_refresh_cards(ui);
175	        }
176	        smart_home_lvgl_trace_tool(ui,
177	                                   payload->tool_name,
178	                                   payload->tool_call_id,
179	                                   payload->error_code == AGENT_OK ? 1 : 0);
180	        break;
181	    case AGENT_EVENT_ERROR:
182	    case AGENT_EVENT_TIMEOUT:
183	        smart_home_lvgl_finish_thinking(ui);
184	        smart_home_lvgl_append_error_bubble(ui, payload->message);
185	        break;
186	    case AGENT_EVENT_RUN_DONE:
187	        if (payload->error_code != AGENT_OK) {
188	            smart_home_lvgl_finish_thinking(ui);
189	            smart_home_lvgl_append_error_bubble(ui, payload->message);
190	        }
191	        break;
192	    default:
193	        break;
194	    }
195	
196	    free(payload);
197	}
