101	int smart_home_lvgl_submit_agent_job(smart_home_lvgl_t *ui, const char *text)
102	{
103	    pthread_t tid;
104	    agent_job_t *job;
105	    int ret;
106	
107	    if (!ui || !ui->app || !text || !text[0]) {
108	        return AGENT_ERROR_INVALID;
109	    }
110	
111	    if (ui->request_inflight) {
112	        smart_home_lvgl_append_error_bubble(ui, "Previous request is still running.");
113	        return AGENT_ERROR_BUSY;
114	    }
115	
116	    job = (agent_job_t *)calloc(1, sizeof(*job));
117	    if (!job) {
118	        smart_home_lvgl_append_error_bubble(ui, "Not enough memory to submit request.");
119	        return AGENT_ERROR_NOMEM;
120	    }
121	
122	    job->ui = ui;
123	    strncpy(job->input, text, sizeof(job->input) - 1);
124	    ui->request_inflight = 1;
125	
126	    {
127	        pthread_attr_t attr;
128	
129	        pthread_attr_init(&attr);
130	        pthread_attr_setstacksize(&attr, 65536);
131	        ret = pthread_create(&tid, &attr, agent_worker_main, job);
132	        pthread_attr_destroy(&attr);
133	    }
134	    if (ret != 0) {
135	        ui->request_inflight = 0;
136	        free(job);
137	        smart_home_lvgl_append_error_bubble(ui, "Failed to create Agent worker.");
138	        return AGENT_ERROR;
139	    }
140	
141	    pthread_detach(tid);
142	    return AGENT_OK;
143	}
