void smart_home_lvgl_trace_iteration(smart_home_lvgl_t *ui,
                                     uint32_t iteration)
{
    lv_obj_t *sep;
    lv_obj_t *label;
    char text[32];

    if (!ui || !ui->chat_trace_body) {
        return;
    }

    ensure_trace_card(ui);
    if (!ui->chat_trace_body) {
        return;
    }

    sep = lv_obj_create(ui->chat_trace_body);
    lv_obj_remove_style_all(sep);
    lv_obj_set_size(sep, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_clear_flag(sep, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_bg_opa(sep, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(sep, 0, 0);
    lv_obj_set_style_pad_all(sep, 0, 0);
    lv_obj_set_flex_flow(sep, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(sep,
                          LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(sep, 4, 0);
    lv_obj_set_style_pad_top(sep, 4, 0);

    snprintf(text, sizeof(text), "Iteration %u", iteration);
    label = smart_home_lvgl_label_create(sep,
                                         text,
                                         SMART_HOME_UI_COLOR_TEXT_MUTED,
                                         11);
    (void)label;

    scroll_chat_to_bottom(ui);
}

void smart_home_lvgl_trace_elapsed(smart_home_lvgl_t *ui,
                                   const char *label_text,
                                   uint64_t event_ms)
{
    lv_obj_t *row;
    lv_obj_t *label;
    char text[64];
    uint64_t elapsed;

    if (!ui || !ui->chat_trace_body || !ui->run_start_ms) {
        return;
    }

    elapsed = event_ms > ui->run_start_ms ? event_ms - ui->run_start_ms : 0;

    row = lv_obj_create(ui->chat_trace_body);
    lv_obj_remove_style_all(row);
    lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_bg_opa(row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(row, 0, 0);
    lv_obj_set_style_pad_all(row, 0, 0);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row,
                          LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(row, 4, 0);

    snprintf(text, sizeof(text), "%s  +%" PRIu64 ".%03us",
             label_text ? label_text : "",
             elapsed / 1000u,
             (unsigned)(elapsed % 1000u));
    label = smart_home_lvgl_label_create(row,
                                         text,
                                         SMART_HOME_UI_COLOR_TEXT_MUTED,
                                         11);
    (void)label;

    scroll_chat_to_bottom(ui);
}

